__forceinline long hs_function_first_active_user()
{
    long result = -1;
    for (long user = 0; user < 4; ++user) {
        if (player_mapping_globals->player_user_mapping[user] != -1) {
            result = user;
            break;
        }
    }
    return result;
}

__forceinline float hs_function_pin(float value, float lower, float upper)
{
    return value > lower ? (value < upper ? value : upper) : lower;
}

// @address 0x216740 player0_set_pitch_evaluate
extern "C" bool player0_set_pitch_evaluate(long player_number, float pitch, long ticks)
{
    long user = hs_function_first_active_user();
    bool success = false;
    short player = 0;
    for (; user != -1; user = players_get_next_user_with_player(user), ++player) {
        if (player == player_number) {
            s_player_control_user_state *control = &((s_player_control_globals *)player_control_globals)->users[user];
            float angle = pitch * 0.01745329238474369f;
            float delta = hs_function_pin(angle, -1.4922565f, 1.4922565f) - control->action.look.pitch;
            control->pitch_kick_ticks = ticks < 1 ? 1 : ticks;
            control->pitch_kick = delta / (float)control->pitch_kick_ticks;
            success = true;
            break;
        }
    }
    return success;
}







