namespace {
static __forceinline long hs_interpolator_start_smooth(long name, float target, float duration)
{
    long result = hs_interpolator_start(name, target, duration);
    if (result != -1) {
        s_scenario_interpolator_state *state = scenario_get_interpolator_state(name, 0);
        state->flags |= 2;
    }
    return result;
}
static __forceinline long hs_interpolator_stop(long name)
{
    long index = -1;
    s_scenario_interpolator_state *state = scenario_get_interpolator_state(name, &index);
    if (state)
        state->flags &= ~1;
    return index;
}
static __forceinline long hs_interpolator_restart(long name)
{
    long index = -1;
    s_scenario_interpolator_state *state = scenario_get_interpolator_state(name, &index);
    if (state && !(state->flags & 1)) {
        float now = game_time_get_safe_in_seconds();
        state->start_time += now - state->last_time;
        state->end_time += now - state->last_time;
        state->last_time = now;
        state->flags |= 1;
    }
    return index;
}
static __forceinline long hs_interpolator_set_current_value(long name, float value)
{
    long index = -1;
    s_scenario_interpolator_state *state = scenario_get_interpolator_state(name, &index);
    if (state) {
        state->current = value;
        state->flags |= 1;
    }
    return index;
}
static __forceinline float hs_interpolator_get_current_time_fraction(long name)
{
    s_scenario_interpolator_state *state = scenario_get_interpolator_state(name, 0);
    float result = 0.0f;
    if (state && state->end_time > state->start_time) {
        result = (state->last_time - state->start_time) / (state->end_time - state->start_time) < 0.0f
            ? 0.0f
            : (state->last_time - state->start_time) / (state->end_time - state->start_time);
        if (state->flags & 2)
            result = scenario_interpolator_time_fraction_smooth(result);
    }
    return result;
}
}

