namespace {
static __forceinline void objects_scripting_attach(long parent_object_index, long parent_marker_name, long child_object_index, long child_marker_name)
{
    if (parent_object_index != -1 && child_object_index != -1) {
        object_datum *child_object = object_get(child_object_index);
        if (child_object->parent_object_index == -1) {
            long ultimate_parent_index = -1;
            long parent_index = parent_object_index;
            while (parent_index != -1) {
                ultimate_parent_index = parent_index;
                parent_index = object_get(parent_index)->parent_object_index;
            }
            if (ultimate_parent_index != child_object_index) {
                if (!((1 << child_object->object_type) & 0xc) || !((item_datum *)child_object)->owner_relation) {
                    object_attach_to_marker_with_type(parent_object_index, parent_marker_name, child_object_index, child_marker_name);
                    if (child_object->parent_object_index == parent_object_index)
                        ::simulation_action_object_update(child_object_index, 0x800);
                }
            }
        }
    }
}
}

