namespace {
static __forceinline long ai_scripting_get_squad(long ai_index)
{
    long squad_ai_index = 0;
    if (ai_index != -1) {
        switch ((unsigned long)ai_index >> 29) {
        case 3:
        case 4: {
            long actor_index = ai_index_get_actor(ai_index);
            if (actor_index != -1) {
                actor_datum *actor = datum_get<actor_datum>(actor_data, actor_index);
                if (actor->squad_index != -1)
                    squad_ai_index = (actor->squad_index & 0xffff) | (1 << 29);
            }
            break;
        }
        }
    }
    return squad_ai_index;
}
}

