namespace {
static __forceinline short hs_function_squad_migrate_form(long ai_index, short squad_index, short form)
{
    short migrated = 0;
    ai_index_actor_iterator iterator;
    ai_index_actor_iterator_new(ai_index, &iterator);
    actor_datum *actor = ai_index_actor_iterator_next(&iterator);
    while (actor != 0) {
        if (actor->squad_index != squad_index && character_get_form(actor->character_index) == form) {
            actor_change_squad(iterator.actor_index, squad_index);
            migrated = (short)(migrated + 1);
        }
        actor = ai_index_actor_iterator_next(&iterator);
    }
    if (migrated > 0)
        ai_handle_squad_placement(squad_index);
    return migrated;
}
}

// @address 0x2c60a0 ?ai_scripting_squad_migrate_form_evaluate@@YAXFJ_N@Z
void ai_scripting_squad_migrate_form_evaluate(short function_index, long thread_index, bool initialize)
{
    hs_value result;
    result.long_value = 0;
    const hs_function_definition *definition = hs_function_table[function_index];
    hs_value *arguments = (hs_value *)hs_arguments_evaluate(thread_index, definition->formal_parameter_count, definition->formal_parameters,
        initialize);
    if (arguments) {
        short migrated = 0;
        long argument_value = arguments[1].long_value;
        short form = arguments[2].short_value;
        if (((unsigned long)argument_value & 0xe0000000) == 0x20000000) {
            short squad_index = (short)argument_value;
            if (squad_index != -1)
                migrated = hs_function_squad_migrate_form(arguments[0].long_value, squad_index, form);
        }
        result.short_value = migrated;
        hs_return(thread_index, result.long_value);
    }
}

