namespace {
static __forceinline long ai_vehicle_get(long ai_index)
{
    long vehicle_index = -1;
    unsigned long type = (unsigned long)ai_index >> 29;
    if (type == 3 || type == 4) {
        long actor_index = ai_index_get_actor(ai_index);
        if (actor_index != -1) {
            actor_datum *actor = (actor_datum *)datum_try_and_get(actor_data, actor_index);
            if (actor) {
                long parent_index = object_get(actor->unit_index)->parent_object_index;
                if (parent_index != -1 && (unsigned char)object_get(parent_index)->object_type == 1)
                    vehicle_index = parent_index;
            }
        }
    }
    return vehicle_index;
}
}

