namespace {
static __forceinline long vs_role(long thread_index, short role)
{
    long ai_index = 0;
    if (role > 0) {
        c_data_iterator<command_script_datum> iterator;
        iterator.m_iterator.data = command_script_data;
        iterator.m_iterator.absolute_index = -1;
        iterator.m_iterator.index = -1;
        while ((iterator.m_datum = (command_script_datum *)data_iterator_next(&iterator.m_iterator)) != 0) {
            if (iterator.m_datum->thread_index == thread_index && iterator.m_datum->role_index == role) {
                ai_index = (iterator.m_datum->actor_index & 0x1fffffff) | (3 << 29);
                break;
            }
        }
    }
    return ai_index;
}
}

