namespace {
static __forceinline void scripted_camera_set_cinematic_scene(long cinematic_tag_index, long scene_index, short flag_space)
{
    if (cinematic_tag_index != -1 && g_camera_script_globals->mode == 5) {
        s_cinematic_scene *definition = (s_cinematic_scene *)tag_get(0, cinematic_tag_index);
        if (definition->shots.count > 0 && ((hs_cinematic_shot *)definition->shots.address)[scene_index].frame_count > 0) {
            g_camera_script_globals->mode = 5;
            g_camera_script_globals->animation_changed = true;
            g_camera_script_globals->camera_track.cinematic_transition = false;
            g_camera_script_globals->camera_track.render_main_camera_to_texture = false;
            g_camera_script_globals->camera_track.cinematic_tag_index = cinematic_tag_index;
            g_camera_script_globals->camera_track.cinematic_flag_space = flag_space;
            g_camera_script_globals->camera_track.cinematic_scene_index = scene_index;
            g_camera_script_globals->camera_track.cinematic_shot_index = -1;
            g_camera_script_globals->camera_track.cinematic_frame = 0;
            g_camera_script_globals->camera_track.cinematic_time = 0;
            g_camera_script_globals->camera_track.cinematic_offset = *global_origin3d;
        }
    }
}
}

