namespace {
static __forceinline void game_pvs_scripted_set_camera_point(short point_index)
{
    if (point_index == -1) {
        game_globals->scripted_type = 0;
    } else {
        s_location location;
        scenario_location_from_point(&location,
            &((scenario_cutscene_camera_point *)global_scenario->cutscene_camera_points.address)[point_index].position);
        if ((unsigned char)location.cluster_reference.bsp_index == 255) {
            game_globals->scripted_type = 0;
        } else {
            game_globals->scripted_type = 2;
            game_globals->scripted_cluster = location.cluster_reference;
        }
    }
}
}

