// @address 0x2d73f8 game_clear_map_completed_evaluate
extern "C" void game_clear_map_completed_evaluate(short function_index, long thread_index, bool initialize)
{
    hs_value *arguments = (hs_value *)hs_macro_function_evaluate(function_index, thread_index, initialize);
    if (arguments) {
        short difficulty = (short)arguments[0].short_value;
        if (difficulty >= 0 && difficulty < 4 && game_globals->options.game_mode == 1 && !game_is_cooperative()) {
            long map = levels_get_campaign_map_index(game_globals->options.campaign_id, game_globals->options.map_id);
            for (long controller_index = 0; controller_index != -1;) {
                s_controller *controller = &g_controller_globals.controllers[controller_index];
                if (controller->in_use())
                    controller->get_player_profile_interface()->set_map_completed_at_difficulty_level(map, difficulty, false, true);
                long next_index = -1;
                if ((unsigned long)controller_index <= 2)
                    next_index = controller_index + 1;
                controller_index = next_index;
            }
        }
        hs_return(thread_index, 0);
    }
}


