namespace {
static __forceinline long game_engine_players_by_team(long team_index)
{
    long object_list_index = -1;
    if ((unsigned long)team_index <= 7) {
        object_list_index = object_list_new();
        if (object_list_index != -1) {
            for (long player_index = ::data_next_index(player_data, -1); player_index != -1;
                player_index = ::data_next_index(player_data, player_index))
            {
                player_datum *player = datum_get<player_datum>(player_data, player_index);
                if (player->unit_index != -1 && player->configuration.host.team_index == team_index)
                    object_list_add(object_list_index, player->unit_index);
            }
        }
    }
    return object_list_index;
}
static __forceinline long hs_function_player_data_next_index(s_data_array *array, long index)
{
    long absolute_index = ::data_next_absolute_index((const ::s_data_array *)(array), (index + 1) & 0xffff);
    long result = -1;
    if (absolute_index != -1)
        result = (*(unsigned short *)(array->data + absolute_index * array->size) << 16) | absolute_index;
    return result;
}
static __forceinline long game_engine_active_player_count_by_team(long team_index)
{
    long count = 0;
    if ((unsigned long)team_index <= 7) {
        for (long player_index = ::data_next_index(player_data, -1); player_index != -1;
            player_index = hs_function_player_data_next_index(player_data, player_index))
        {
            player_datum *player = datum_get<player_datum>(player_data, player_index);
            if (player->configuration.host.team_index == team_index && (player->unit_index != -1 || player->lives > 0))
                count++;
        }
    }
    return count;
}
}

