// @address 0x2de598 ai_set_erase_time_evaluate
extern "C" void ai_set_erase_time_evaluate(short function_index, long thread_index, bool initialize)
{
    hs_value *arguments = (hs_value *)hs_macro_function_evaluate(function_index, thread_index, initialize);
    if (arguments) {
        long ai_index = arguments[0].long_value;
        short delta = (short)arguments[1].short_value;
        long erase_tick;
        if (delta > 0)
            erase_tick = game_time_globals->time + delta;
        else
            erase_tick = -1;
        short erase_time = (short)erase_tick;
        ai_index_actor_iterator iterator;
        ai_index_actor_iterator_new(ai_index, &iterator);
        actor_datum *actor = ai_index_actor_iterator_next(&iterator);
        while (actor) {
            if (actor->active)
                actor->erase_time = erase_time;
            else
                actor_erase(iterator.actor_index, false);
            actor = ai_index_actor_iterator_next(&iterator);
        }
        hs_return(thread_index, 0);
    }
}



