// @address 0x5067a8 ai_scripting_attach_units_evaluate
extern "C" long ai_scripting_attach_units_evaluate(long object_list_index, long ai_index)
{
    long reference_index;
    long object_index = object_list_get_first_or_none(object_list_index, &reference_index);
    if (object_index != -1) {
        long next_reference = reference_index;
        do {
            ai_scripting_attach_unit(object_index, ai_index);
            object_index = object_list_get_next(object_list_index, &next_reference);
        } while (object_index != -1);
    }
    return object_index;
}

