// @address 0x2ce658 ?vs_cs_play_line_evaluate@@YAXFJ_N@Z
void vs_cs_play_line_evaluate(short function_index, long thread_index, bool initialize)
{
    const hs_function_definition *definition = hs_function_table[function_index];
    hs_value *arguments = (hs_value *)hs_arguments_evaluate(thread_index, definition->formal_parameter_count, definition->formal_parameters,
        initialize);
    if (arguments) {
        long ai_index = arguments[0].long_value;
        bool active = arguments[1].boolean_value;
        hs_thread *thread = hs_function_get_thread(thread_index);
        bool started = false;
        ai_index_actor_iterator iterator;
        ai_index_actor_iterator_new(ai_index, &iterator);
        if (ai_index_actor_iterator_next(&iterator)) {
            do {
                long actor_index = iterator.actor_index;
                long command_script_index = cs_index_from_thread(actor_index, thread_index, true);
                if (command_script_index != -1) {
                    started = true;
                    if (actor_index != -1)
                        mission_dialogue_play_line(actor_index, command_script_index, active, arguments[2].long_value, 0);
                }
            } while (ai_index_actor_iterator_next(&iterator));
        }
        if (started && active) {
            thread->ai_index = ai_index;
            thread->sleep_until = -3;
        }
        hs_return(thread_index, 0);
    }
}

