// @address 0x2c4f38 ?ai_scripting_place_in_vehicle_evaluate@@YAXFJ_N@Z
void ai_scripting_place_in_vehicle_evaluate(short p0, long p1, bool p2)
{
    hs_function_definition *definition = ((hs_function_definition **)hs_function_table)[p0];
    long *arguments = hs_arguments_evaluate(p1, definition->formal_parameter_count, definition->formal_parameters, p2);
    if (arguments != 0) {
        long squad_group_index = arguments[0];
        long squad_identifier = arguments[1];
        if (squad_group_index != -1 && squad_identifier != -1 && (squad_identifier & 0xe0000000) == 0x20000000) {
            unsigned int objective_index = (unsigned short)squad_identifier;
            ai_index_squad_iterator iterator;
            ::ai_index_squad_iterator_new(squad_group_index, &iterator);
            if (ai_index_squad_iterator_next(&iterator) != 0) {
                do {
                    ::squad_create(iterator.squad_index, -1, -1, -1, 0, 1, 0);
                    squad_load_in_squad(iterator.squad_index, objective_index);
                } while (ai_index_squad_iterator_next(&iterator) != 0);
            }
            ai_globals->current_squad = squad_group_index;
        }
        hs_return(p1, 0);
    }
}


